import {unlockAudio,configureAudio,parkAudio,soundFX} from './audio.js';
import {RULES,createState,clone,batter,rollDice,applyRecord,replay,playFromTurn,situationOdds} from './engine.js';
import {esc,cardHTML,dieHTML,paintField,animatePlay,animateDice,setSpeed,setSound} from './field.js';
import {recap,career,battingLine,gameEvents} from './stats.js';
import {standings} from './league.js';
import * as Cloud from './cloud.js';
const $=s=>document.querySelector(s),main=$('#main'),modal=$('#modal'),BASEKEY='cardpark.v1.';
const ICONS=['⚾','🐯','🦝','🦊','🐻','🦅','🐺','🦁','🔥','⚡','🌵','🦈'];
function read(k,f){try{return JSON.parse(localStorage.getItem(BASEKEY+k))??f;}catch{return f;}}
function write(k,v){try{localStorage.setItem(BASEKEY+k,JSON.stringify(v));return true;}catch{toast('Device storage is full. Free some space so games can save.');return false;}}
function remove(k){try{localStorage.removeItem(BASEKEY+k);}catch{}}
const makeTeam=(name,color,names,icons)=>({name,color,players:names.map((name,i)=>({name,number:i+1,icon:icons[i],photo:''}))});
const defaults=[makeTeam('The Homegrown','#315c48',['Ace','Scout','Slugger','Rookie'],['🐯','🦊','🐻','🦝']),makeTeam('The Night Owls','#b66343',['Dash','Maverick','Rocket','Skip'],['🦅','🐺','⚡','🦁'])];
function validTeam(t){return t&&typeof t.name==='string'&&/^#[a-f0-9]{6}$/i.test(t.color)&&t.players?.length===4&&t.players.every(p=>typeof p.name==='string'&&typeof p.photo==='string'&&p.photo.length<=40000);}
let teams=read('teams',clone(defaults));if(!Array.isArray(teams)||!teams.every(validTeam))teams=clone(defaults);
let view='home',generation=0,current=null,session=null,busy=false,replaying=false,speed=read('speed',1),sound=read('sound',true),soundVolume=read('volume',.8),crowdSound=read('crowd',true),authMode='signin',onlineList=[],openGames=[],leagueList=[],lobbyTab='mine',leagueCurrent=null,returnLeague='',subs=[],presenceData={},heartbeatTimer,clockTimer,autoTimer,toastTimer;
let displayedState=null,displayRevision=0,actionQueue=[],seenActions=new Set(),localActions=new Set(),eventEpoch=0,eventRunning=false,reportCache=null,reportLoading=false,replayEpoch=0,uiError='';
if(![1,2,4].includes(speed))speed=1;setSpeed(speed);configureAudio({enabled:sound,volume:soundVolume,crowd:crowdSound});setSound(sound);
$('#sound').textContent=sound?'🔊':'🔇';
document.addEventListener('pointerdown',unlockAudio,{capture:true});document.addEventListener('keydown',unlockAudio,{capture:true});
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function errorText(e){return Cloud.friendly(e);}
function teamLabel(t){return esc(t?.name||'Open seat');}
function closeModal(){modal.close();}
function showModal(title,html){$('#modalBody').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="close" data-close aria-label="Close dialog">×</button></div>${html}`;if(!modal.open)modal.showModal();modal.querySelector('[data-close]').onclick=closeModal;}
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
function enter(v){if(view==='game'&&current&&Cloud.user)Cloud.presence(current.code,false).catch(()=>{});subs.forEach(u=>u?.());subs=[];clearInterval(heartbeatTimer);clearInterval(clockTimer);clearTimeout(autoTimer);generation++;displayedState=null;displayRevision=0;eventEpoch++;replayEpoch++;eventRunning=false;actionQueue=[];seenActions=new Set();localActions=new Set();busy=false;replaying=false;reportCache=null;reportLoading=false;uiError='';presenceData={};view=v;parkAudio(v==='game');window.scrollTo({top:0,behavior:'instant'});return generation;}
function keep(g,u){if(g===generation)subs.push(u);else u?.();}
function saveSession(){if(session?.kind==='offline')write('offline',session);}
function accountLabel(){$('#account').textContent=Cloud.user?(Cloud.user.displayName?.split(' ')[0]||Cloud.user.email?.split('@')[0]||'Account'):'Sign in';}
Cloud.onUser(()=>accountLabel());
$('#brand').onclick=()=>{if(busy&&!eventRunning&&!replaying){toast('Finishing this play…');return;}home();};$('#help').onclick=rules;$('#sound').onclick=soundSettings;$('#account').onclick=()=>Cloud.user?accountDialog():authDialog();
function home(){
 enter('home');returnLeague='';current=null;session=null;const saved=read('offline',null);
 main.innerHTML=`<section class="hero"><div class="hero-copy"><div class="eyebrow">Your ballpark. Your people.</div><h1>Small teams.<br><em>Big innings.</em></h1><p class="intro">Four cards. Two dice. One clutch decision.<br>Your next great rivalry starts here.</p><div class="buttonrow"><button class="btn" id="quickplay">Play ball ↗</button><button class="btn outline" id="myteam">Customize lineup</button><button class="btn secondary" id="homeStats">My stats</button></div><p class="fineprint">LIVE ROLLS · OPEN GAMES · LEAGUES & PLAYOFFS</p></div><div class="hero-art"><div class="hero-diamond"></div><div class="hero-card">${cardHTML(teams[0].players[0],teams[0])}</div><div class="hero-card second">${cardHTML(teams[1].players[0],teams[1])}</div><div class="hero-dice">${dieHTML(5)}${dieHTML(6)}</div></div></section>${saved?`<div class="save-card row"><div><strong>${saved.finalized?'Your last ballgame':'A ballgame is waiting'}</strong><p class="note">${teamLabel(saved.teams[0])} vs. ${teamLabel(saved.teams[1])} · ${saved.state.runs.join(' – ')}</p></div><button class="btn" id="resume">${saved.finalized?'Recap':'Resume'} →</button></div>`:''}<div class="section-title row"><h2>Meet you at the park.</h2><span class="pill">3 · 6 · 9 INNINGS</span></div><section class="mode-grid"><button class="mode" data-mode="solo"><span class="mode-icon">⚾</span><h3>Solo ballgame</h3><p>Your lineup against the park crew. Same dice. One clutch reroll each.</p><span class="arrow">PLAY OFFLINE ↗</span></button><button class="mode" data-mode="local"><span class="mode-icon">🤝</span><h3>Pass & play</h3><p>Two teams on one device. A whole ballpark in your pocket.</p><span class="arrow">SAME DEVICE ↗</span></button><button class="mode" data-mode="online"><span class="mode-icon">🏟</span><h3>The clubhouse</h3><p>Find open games, watch live rolls, join a league, and chase a title.</p><span class="arrow">ONLINE GAMES & LEAGUES ↗</span></button></section><div class="footer row"><span>CARDPARK / 2.0</span><button class="back" id="homeRules" style="margin:0">How to play →</button></div>`;
 $('#quickplay').onclick=()=>setup('solo');$('#myteam').onclick=()=>setup('team');$('#homeStats').onclick=()=>showStats(false);$('#homeRules').onclick=rules;main.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>b.dataset.mode==='online'?lobby():setup(b.dataset.mode));$('#resume')?.addEventListener('click',()=>{enter('game');session=saved;session.kind='offline';session.rolls??=session.turnRolls||[];session.start??=session.turnStart||createState(session.state.innings);session.pending??=false;session.finalized??=session.state.over&&!session.pending;session.id??=String(session.created||Date.now());if(session.finalized)archiveOffline();renderGame();});
}
function setup(mode){
 enter('setup');current=null;const work=clone(teams),online=mode==='online',only=mode==='team';
 main.innerHTML=`<div class="setup"><button class="back" id="setupBack">← ${online?'Clubhouse':'Home'}</button><div class="eyebrow">${only?'MAKE IT YOURS':online?'OPEN A SEAT IN THE CLUBHOUSE':'SET THE LINEUP'}</div><h2>${only?'Your starting four.':'Let’s make a ballgame.'}</h2><p class="note">Photos and names are cosmetic. Every team gets one Clutch Batter reroll per game.</p><form id="setupForm">${!only?`<section class="panel"><div class="form-grid"><div><label for="innings">Innings</label><select id="innings"><option>3</option><option selected>6</option><option>9</option></select></div>${online?'<div><label for="gamePin">Optional join code</label><input id="gamePin" maxlength="24" autocomplete="off" placeholder="Leave empty: anyone can join"></div>':''}</div>${online?'<p class="note" style="margin:12px 0 0">Your game appears in Find a game. A code locks the seat; leaving it empty makes it open to any signed-in player.</p>':''}</section>`:''}${teamEditor(work[0],0,online||only?'Your team':'Away · bats first')}${!online&&!only?teamEditor(work[1],1,mode==='solo'?'Park crew · computer':'Home · bats second'):''}<p class="error" id="setupError" role="alert"></p><button class="btn wide" id="startGame">${only?'Save lineup':online?'Create ballgame':'Play ball →'}</button></form></div>`;$('#setupBack').onclick=()=>online?lobby():home();bindEditors(work);
 $('#setupForm').onsubmit=async e=>{e.preventDefault();teams=work.map(cleanTeam);if(!write('teams',teams))return;const btn=$('#startGame');btn.disabled=true;try{if(only){if(Cloud.user)await Cloud.saveTeam(teams[0]);home();toast('Lineup saved.');return;}const innings=Number($('#innings').value);if(online){await Cloud.saveTeam(teams[0]);const code=await Cloud.createMatch(teams[0],innings,{pin:$('#gamePin').value.trim()});openMatch(code);return;}const start=()=>{enter('game');session={kind:'offline',id:crypto.randomUUID(),mode,teams:clone(teams),state:createState(innings),start:createState(innings),rolls:[],history:[],log:[],pending:false,finalized:false};saveSession();renderGame();};const old=read('offline',null);if(old&&!old.finalized&&!old.state.over){showModal('Start a new ballgame?',`<p class="note">This replaces the unfinished offline game on this device.</p><div class="buttonrow"><button class="btn" id="confirmNew">Start new game</button><button class="btn secondary" id="keepOld">Keep current game</button></div>`);$('#confirmNew').onclick=()=>{closeModal();start();};$('#keepOld').onclick=closeModal;modal.addEventListener('close',()=>{if(btn.isConnected)btn.disabled=false;},{once:true});}else start();}catch(err){$('#setupError').textContent=errorText(err);btn.disabled=false;}};
}
function rules(){showModal('Two dice. One big decision.',`<p class="rules-copy">The dice chart is unchanged. Three outs ends a half-inning. Choose 3, 6, or 9 innings; ties go to extras.</p><table class="rules-grid">${Object.entries(RULES).map(([k,v])=>`<tr><td>${k}</td><td>${v[1]}</td></tr>`).join('')}</table><div class="rules-copy"><p>Hits move every runner the number of bases hit. Walks move forced runners. Ordinary outs hold runners. Double plays retire the batter plus the runner nearest home (one out if empty or already two out). Sacrifice flies advance every runner one base unless they make the third out.</p><p><strong>Clutch Batter:</strong> each team can reroll its latest at-bat once per game. Use it after seeing a result, before your next roll or confirming the half-inning. Both dice reroll; the new result is final, even if worse. The original play is completely reversed, including runs, outs, and stats. You may use it on a third out or provisional game-ending roll.</p><p><strong>A little skill:</strong> save your clutch for a high-leverage situation. The scouting panel shows out/on-base odds and expected runs for the current base situation. Your decision is when to spend the reroll; player cards retain equal odds.</p><p>At three outs, tap <strong>Keep play & end inning</strong> when you’re happy with the result. This leaves room to use Clutch Batter. Online opponents receive each individual roll immediately after it saves; they do not need to wait for the inning to finish.</p><p>Four-card rule: a player already on base is skipped in the batting order. No steals, extra-base choices, or push notifications.</p><p>Leagues have 3–12 teams, equal regular-season games per team, then a single-elimination playoff. With an odd number of teams, games per team must be even. Standings use win percentage, wins, head-to-head, run differential, then runs scored.</p></div>`);}
async function lobby(){const g=enter('lobby');session=null;current=null;renderLobby('Connecting…');try{await Cloud.connect();if(g!==generation)return;accountLabel();if(!Cloud.user){renderLobby();return;}keep(g,await Cloud.watchList(list=>{if(g!==generation)return;onlineList=list;renderLobby();},e=>lobbyError(g,e)));keep(g,await Cloud.watchOpenGames(list=>{if(g!==generation)return;openGames=list;renderLobby();},e=>lobbyError(g,e)));keep(g,await Cloud.watchLeagues(list=>{if(g!==generation)return;leagueList=list;renderLobby();},e=>lobbyError(g,e)));}catch(e){lobbyError(g,e);}}
function lobbyError(g,e){if(g===generation)renderLobby(errorText(e),true);}
function renderLobby(message='',error=false){
 const tabs=[['mine','My games'],['open','Find a game'],['leagues','Leagues'],['stats','Stats']];
 let content='';if(Cloud.user){if(lobbyTab==='mine')content=onlineList.length?onlineList.map(m=>`<button class="match-item" data-open="${esc(m.code)}"><div class="row"><span class="matchtitle">${teamLabel(m.teams[0])} <span class="muted">vs.</span> ${teamLabel(m.teams[1])}</span><span class="pill">${m.status==='complete'?'FINAL':m.status==='waiting'?'OPEN SEAT':m.turnUid===Cloud.user.uid?'YOUR TURN':'THEIR TURN'}</span></div><small>${m.state.runs.join(' – ')} · ${m.state.innings} innings${m.leagueId?' · LEAGUE':''}</small></button>`).join(''):'<div class="empty panel">No ballgames yet. Create one or find an open seat.</div>';
 else if(lobbyTab==='open')content=openGames.filter(g=>g.owner!==Cloud.user.uid).map(g=>`<button class="match-item" data-join="${esc(g.code)}" data-locked="${g.locked?'1':'0'}"><div class="row"><span class="matchtitle">${esc(g.name)} <span class="muted">are waiting</span></span><span class="pill">${g.locked?'🔒 CODE REQUIRED':'OPEN SEAT'}</span></div><small>${g.innings} innings · Tap to join as the home team</small></button>`).join('')||'<div class="empty panel">No open seats right now. Create a ballgame and it will appear here.</div>';
 else if(lobbyTab==='leagues')content=`<button class="btn wide" id="newLeague">Create a league ↗</button>${leagueList.map(l=>`<button class="match-item" data-league="${esc(l.id)}"><div class="row"><span class="matchtitle">${esc(l.name)}</span><span class="pill">${l.memberIds.includes(Cloud.user.uid)?'YOUR LEAGUE':l.status==='forming'?'JOINING':'IN SEASON'}</span></div><small>${l.memberIds.length}/${l.cap} teams · ${l.gamesPerTeam} games/team · ${l.innings} innings · ${esc(l.status)}</small></button>`).join('')||'<div class="empty">Build a league and invite your rivals.</div>'}`;
 else content=statsHTML(career(onlineList,Cloud.user.uid),'Online career');}
 main.innerHTML=`<div class="setup"><button class="back" id="lobbyBack">← Home</button><div class="eyebrow">THE CLUBHOUSE</div><h2>There’s always a game here.</h2><p class="note">Join an open seat, protect one with a code, or play a full league season.</p>${Cloud.user?`<div class="buttonrow"><button class="btn" id="createOnline">New ballgame ↗</button><button class="btn outline" id="joinOnline">Game ID</button></div><div class="tabs clubhouse-tabs">${tabs.map(([id,label])=>`<button data-tab="${id}" class="${lobbyTab===id?'active':''}">${label}</button>`).join('')}</div><p class="${error?'error':'note'}" role="status">${esc(message)}</p><div class="matchlist">${content}</div>`:`<section class="panel"><p class="note">Sign in to find other players, save stats, and join leagues.</p><button class="btn" id="lobbySignin">Sign in / create account</button><p class="${error?'error':'note'}">${esc(message)}</p></section>`}</div>`;
 $('#lobbyBack').onclick=home;$('#lobbySignin')?.addEventListener('click',authDialog);$('#createOnline')?.addEventListener('click',()=>setup('online'));$('#joinOnline')?.addEventListener('click',()=>joinDialog());$('#newLeague')?.addEventListener('click',createLeagueDialog);main.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{lobbyTab=b.dataset.tab;renderLobby();});main.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openMatch(b.dataset.open));main.querySelectorAll('[data-join]').forEach(b=>b.onclick=()=>joinDialog(b.dataset.join,b.dataset.locked==='1'));main.querySelectorAll('[data-league]').forEach(b=>b.onclick=()=>openLeague(b.dataset.league));
}
function joinDialog(code='',locked=true){showModal('Take the home dugout.',`<p class="note">You’ll use <strong>${teamLabel(teams[0])}</strong>. Customize your lineup from Home before joining if needed.</p><form id="joinForm"><label for="inviteCode">Game ID</label><input id="inviteCode" value="${esc(code||read('invite',''))}" maxlength="8" autocapitalize="characters" autocomplete="off" required>${locked?'<div class="form-group"><label for="joinPin">Join code, if the host set one</label><input id="joinPin" type="password" autocomplete="off" maxlength="24"></div>':''}<p class="error" id="joinError"></p><button class="btn wide" id="joinSubmit">Join ballgame</button></form>`);$('#joinForm').onsubmit=async e=>{e.preventDefault();$('#joinSubmit').disabled=true;try{await Cloud.saveTeam(teams[0]);const id=await Cloud.joinMatch($('#inviteCode').value,teams[0],$('#joinPin')?.value||'');remove('invite');closeModal();openMatch(id);}catch(err){$('#joinError').textContent=err.code?.includes('permission-denied')?'That join code was not accepted, or the game has filled. Check the code and try again.':errorText(err);$('#joinSubmit').disabled=false;}};}
function teamEditor(team,index,label){return `<section class="team-edit" data-team="${index}"><div class="row"><h3>${label}</h3><span class="pill">4 PLAYER LINEUP</span></div><div class="form-grid"><div><label for="teamname${index}">Team name</label><input id="teamname${index}" data-teamname maxlength="24" value="${esc(team.name)}" required></div><div><label for="teamcolor${index}">Card color</label><input id="teamcolor${index}" type="color" data-teamcolor value="${esc(team.color)}"></div></div><div class="edit-roster">${team.players.map((p,i)=>`<div class="edit-player" data-player="${i}"><button class="photo-edit" type="button" aria-label="Customize photo for ${esc(p.name)}">${p.photo?`<img src="${p.photo}" alt="">`:esc(p.icon)}</button><input class="pname" aria-label="Player ${i+1} name" maxlength="18" value="${esc(p.name)}" required><input class="pnumber" aria-label="Player ${i+1} number" inputmode="numeric" type="number" min="0" max="99" value="${esc(p.number)}"><div class="photo-actions"><button type="button" class="changeicon">Choose icon</button>${p.photo?'<button type="button" class="removephoto">Remove photo</button>':''}</div></div>`).join('')}</div></section>`;}
function bindEditors(work){
 main.querySelectorAll('[data-team]').forEach(section=>{
  const t=work[+section.dataset.team];
  section.querySelector('[data-teamname]').oninput=e=>t.name=e.target.value;
  section.querySelector('[data-teamcolor]').oninput=e=>t.color=e.target.value;
  section.querySelectorAll('[data-player]').forEach(div=>{
   const p=t.players[+div.dataset.player];
   div.querySelector('.pname').oninput=e=>p.name=e.target.value;
   div.querySelector('.pnumber').oninput=e=>p.number=Math.max(0,Math.min(99,Number(e.target.value)||0));
   const refresh=()=>{div.querySelector('.photo-edit').innerHTML=p.photo?`<img src="${p.photo}" alt="">`:esc(p.icon);};
   div.querySelector('.photo-edit').onclick=()=>photoDialog(p,refresh);
   div.querySelector('.changeicon').onclick=()=>{showModal('Pick your player.',`<p class="note">Choose an icon. Every card plays with the same odds.</p><div class="preset-row">${ICONS.map(x=>`<button class="pickicon" aria-label="${x}">${x}</button>`).join('')}</div>`);modal.querySelectorAll('.pickicon').forEach(b=>b.onclick=()=>{p.icon=b.textContent;p.photo='';refresh();closeModal();});};
   div.querySelector('.removephoto')?.addEventListener('click',()=>{p.photo='';refresh();});
  });
 });
}
function cleanTeam(t){const c=clone(t);c.name=c.name.trim()||'Ball Club';c.players.forEach((p,i)=>{p.name=p.name.trim()||`Player ${i+1}`;p.number=Math.max(0,Math.min(99,Number(p.number)||0));});return c;}
async function photoDialog(p,done){
 showModal('Make it your card.',`<p class="note">Choose a photo from your phone. Move the sliders to frame the face. Photos are compressed before saving.</p><input id="photoFile" type="file" accept="image/*"><div id="photoWork" hidden><canvas id="cropCanvas" class="crop-preview" width="240" height="300"></canvas><label>Zoom<input id="cropZoom" type="range" min="1" max="3" step="0.01" value="1"></label><label>Horizontal position<input id="cropX" type="range" min="0" max="1" step="0.01" value="0.5"></label><label>Vertical position<input id="cropY" type="range" min="0" max="1" step="0.01" value="0.5"></label><button id="usePhoto" class="btn wide">Use this photo</button></div><p id="photoError" class="error" role="alert"></p>`);
 const input=$('#photoFile');let img;
 const draw=()=>{const c=$('#cropCanvas');if(!c||!img)return;const z=Number($('#cropZoom').value),scale=Math.max(c.width/img.naturalWidth,c.height/img.naturalHeight)*z,w=img.naturalWidth*scale,h=img.naturalHeight*scale,x=(c.width-w)*Number($('#cropX').value),y=(c.height-h)*Number($('#cropY').value);const ctx=c.getContext('2d');ctx.fillStyle='#ddd7c4';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(img,x,y,w,h);};
 input.onchange=async()=>{try{const f=input.files[0];if(!f)return;if(f.size>25*1024*1024)throw Error('Choose a photo smaller than 25 MB.');const url=URL.createObjectURL(f);img=new Image();try{await new Promise((res,rej)=>{img.onload=res;img.onerror=()=>rej(Error('This photo format could not be opened. Try JPG, PNG, or a screenshot.'));img.src=url;});}finally{URL.revokeObjectURL(url);}$('#photoWork').hidden=false;$('#photoError').textContent='';draw();}catch(e){$('#photoError').textContent=e.message;}};
 ['cropZoom','cropX','cropY'].forEach(id=>$('#'+id).oninput=draw);
 $('#usePhoto').onclick=()=>{let q=.82,data;const c=$('#cropCanvas');do{data=c.toDataURL('image/jpeg',q);q-=.1;}while(data.length>36000&&q>.1);if(data.length>40000){toast('Try zooming out or choosing a simpler photo.');return;}p.photo=data;done();closeModal();};
}

function authDialog(){
 showModal('Welcome to the club.',`<p class="note">Sign in for private games with friends. Offline games never need an account.</p><button class="btn outline wide" id="googleLogin">Continue with Google</button><div class="divider">or use your email</div><div class="tabs"><button id="tabSignin" class="${authMode==='signin'?'active':''}">Sign in</button><button id="tabSignup" class="${authMode==='signup'?'active':''}">Create account</button></div><form id="authForm"><div class="form-group"><label for="email">Email</label><input id="email" type="email" autocomplete="email" required></div><div class="form-group"><label for="password">Password</label><input id="password" type="password" minlength="6" autocomplete="${authMode==='signup'?'new-password':'current-password'}" required></div><p class="error statusline" id="authError" role="alert"></p><button class="btn wide" id="authSubmit">${authMode==='signup'?'Create account':'Sign in'}</button></form><button class="back" id="forgot" style="margin:17px 0 0">Forgot password?</button>`);
 $('#tabSignin').onclick=()=>{authMode='signin';authDialog();};$('#tabSignup').onclick=()=>{authMode='signup';authDialog();};
 const finish=async()=>{accountLabel();closeModal();toast('You’re signed in.');if(view==='lobby'){await lobby();const code=read('invite',null);if(code){joinDialog();$('#inviteCode').value=code;remove('invite');}}};
 $('#googleLogin').onclick=async()=>{const btn=$('#googleLogin');btn.disabled=true;try{await Cloud.google();await finish();}catch(e){$('#authError').textContent=errorText(e);btn.disabled=false;}};
 $('#authForm').onsubmit=async e=>{e.preventDefault();const btn=$('#authSubmit');btn.disabled=true;$('#authError').textContent='Connecting…';try{await Cloud.login($('#email').value.trim(),$('#password').value,authMode==='signup');await finish();}catch(err){$('#authError').textContent=errorText(err);btn.disabled=false;}};
 $('#forgot').onclick=async()=>{const email=$('#email').value.trim();if(!email){$('#authError').textContent='Enter your email above first.';return;}try{await Cloud.reset(email);$('#authError').textContent='If an account exists, check your inbox for a reset email.';}catch(e){$('#authError').textContent=errorText(e);}};
}
function accountDialog(){showModal('Your clubhouse account.',`<p class="note">${esc(Cloud.user?.email||Cloud.user?.displayName)}</p><p class="note">Your online games are linked to this account. Offline games and unfinished turns stay on this device.</p><div class="buttonrow"><button class="btn" id="cloudLineup">Load saved lineup</button><button class="btn secondary" id="signout">Sign out</button></div><p class="error" id="accountError"></p>`);$('#cloudLineup').onclick=async()=>{try{const t=await Cloud.loadTeam();if(!validTeam(t))throw Error('No saved online lineup yet. Create or join a game to save one.');teams[0]=t;write('teams',teams);closeModal();toast('Your saved lineup is ready.');if(view==='home')home();}catch(e){$('#accountError').textContent=errorText(e);}};$('#signout').onclick=async()=>{try{await Cloud.logout();closeModal();home();toast('Signed out.');}catch(e){$('#accountError').textContent=errorText(e);}};}

function soundSettings(){
 unlockAudio();showModal('Bring the ballpark to life.',`<p class="note">Dice clatter, bat cracks, glove catches, footsteps, scoring fanfares, and a cheering crowd.</p><div class="row"><label for="soundEnabled" style="margin:0">Game sounds</label><input type="checkbox" id="soundEnabled" ${sound?'checked':''}></div><div class="form-group"><label for="soundVolume">Volume <span id="volumeValue">${Math.round(soundVolume*100)}%</span></label><input id="soundVolume" type="range" min="0" max="1" step=".05" value="${soundVolume}"></div><div class="row"><label for="crowdEnabled" style="margin:0">Crowd atmosphere & cheers</label><input type="checkbox" id="crowdEnabled" ${crowdSound?'checked':''}></div><button class="btn wide" id="testAudio" style="margin-top:22px">Test the ballpark sound ⚾</button><p class="fineprint" style="margin-top:14px">Your device’s media volume controls the final level. Sound pauses when the game is hidden.</p>`);
 const apply=()=>{sound=$('#soundEnabled').checked;soundVolume=Number($('#soundVolume').value);crowdSound=$('#crowdEnabled').checked;write('sound',sound);write('volume',soundVolume);write('crowd',crowdSound);configureAudio({enabled:sound,volume:soundVolume,crowd:crowdSound});$('#volumeValue').textContent=Math.round(soundVolume*100)+'%';$('#sound').textContent=sound?'🔊':'🔇';$('#sound').setAttribute('aria-pressed',String(sound));};
 $('#soundEnabled').onchange=apply;$('#soundVolume').oninput=apply;$('#crowdEnabled').onchange=apply;$('#testAudio').onclick=()=>{unlockAudio();soundFX('homerun');};
}
async function openMatch(code,leagueId=''){
 const g=enter('game');returnLeague=leagueId;session=null;current=null;main.innerHTML='<div class="empty">Opening the ballpark…</div>';
 try{let m=await Cloud.getMatch(code);if(m.v<2&&m.status!=='complete'&&m.players.includes(Cloud.user.uid)){await Cloud.upgradeMatch(code,read(`draft.${Cloud.user.uid}.${code}`,null));m=await Cloud.getMatch(code);}if(g!==generation)return;setMatch(m,true);
  keep(g,await Cloud.watchEvents(code,displayRevision,events=>{if(g!==generation)return;events.forEach(queueAction);},e=>{if(g===generation){uiError=errorText(e);if(!busy)renderGame();}}));
  keep(g,await Cloud.watchMatch(code,m=>{if(g!==generation)return;setMatch(m);},e=>gameFailure(g,e)));
  keep(g,await Cloud.watchPresence(code,p=>{if(g===generation){presenceData=p;updatePresenceLabel();}},()=>{}));
  sendPresence();heartbeatTimer=setInterval(()=>{if(!document.hidden)sendPresence();},25000);clockTimer=setInterval(updatePresenceLabel,5000);
 }catch(e){gameFailure(g,e);}
}
function gameFailure(g,e){if(g!==generation)return;main.innerHTML=`<div class="setup"><button class="back" id="gameErrorBack">← Clubhouse</button><h2>Couldn’t open the park.</h2><p class="error">${esc(errorText(e))}</p></div>`;$('#gameErrorBack').onclick=lobby;}
function setMatch(m,initial=false){
 if(current&&m.revision<current.revision)return;const old=current;current=m;if(old&&m.seq>old.seq&&displayRevision>=m.revision&&!eventRunning)write(`seen.${m.code}`,m.seq);
 if(m.status==='waiting'){waitingRoom(m);return;}
 session={kind:'online',id:m.code,code:m.code,mode:'online',teams:m.teams,state:clone(m.state),start:clone(m.turnStart),rolls:clone(m.progress?.rolls||[]),pending:!!m.progress?.ended,finalized:m.status==='complete',seq:m.seq,revision:m.revision,log:turnLog(m.turnStart,m.progress?.rolls||[])};
 if(initial||!displayedState){displayedState=clone(m.state);displayRevision=m.revision;}
 else if(m.lastAction&&m.lastAction.revision>displayRevision)queueAction(m.lastAction);
 if(old?.turnUid!==m.turnUid&&m.turnUid===Cloud.user.uid)soundFX('yourturn');
 if(!busy&&!replaying&&m.revision<=displayRevision)renderGame();
}
function turnLog(start,rolls){let s=clone(start),log=[];for(const r of rolls){const b=clone(s),x=applyRecord(s,r);s=x.state;log.push({...x.event,inning:b.inning,half:b.half});}return log;}
function queueAction(a){if(!a||a.revision<=displayRevision||seenActions.has(a.id)||actionQueue.some(x=>x.id===a.id))return;actionQueue.push(a);actionQueue.sort((a,b)=>a.revision-b.revision);pumpActions();}
function actionResult(a){const before=JSON.parse(a.beforeJSON),result=applyRecord(before,{dice:a.dice,clutch:a.clutch,originalDice:a.originalDice});return {before,result};}
async function pumpActions(){
 if(eventRunning||busy||replaying||view!=='game'||document.hidden||!session)return;
 const g=generation,epoch=eventEpoch;eventRunning=true;busy=true;
 try{while(actionQueue.length&&g===generation&&epoch===eventEpoch&&!document.hidden){const a=actionQueue[0];if(a.revision<=displayRevision){actionQueue.shift();continue;}if(a.revision!==displayRevision+1||localActions.has(a.id))break;actionQueue.shift();const {before,result}=actionResult(a);displayedState=before;renderGame(before);const status=$('#liveNow');if(status)status.textContent=`${a.clutch?'CLUTCH REROLL':'LIVE ROLL'} · ${session.teams[result.event.team].players[result.event.batter].name}`;
   await animateDice($('#dice'),a.dice);if(g!==generation||epoch!==eventEpoch)break;await animatePlay($('#field'),before,result,session.teams);if(g!==generation||epoch!==eventEpoch)break;displayedState=clone(result.state);displayRevision=a.revision;seenActions.add(a.id);session.lastDice=a.dice;markLiveSeen();renderGame();}
 }catch(e){uiError=errorText(e);}finally{if(g===generation&&epoch===eventEpoch){busy=false;eventRunning=false;renderGame();}}
}
function catchUp(){eventEpoch++;eventRunning=false;busy=false;actionQueue=[];if(current){displayedState=clone(current.state);displayRevision=current.revision;markLiveSeen();}renderGame();}
function markLiveSeen(){if(current?.lastTurn&&displayRevision>=current.revision)write(`seen.${current.code}`,current.seq);}
function sendPresence(active=!document.hidden){if(current&&Cloud.user&&navigator.onLine)Cloud.presence(current.code,active).catch(()=>{});}
function opponentHere(){const id=current?.players.find(x=>x!==Cloud.user?.uid),p=presenceData[id];return !!(navigator.onLine&&p?.active&&Date.now()-(p.at?.toMillis?.()||0)<75000);}
function updatePresenceLabel(){const e=$('#onlinePresence');if(e){e.textContent=!navigator.onLine?'OFFLINE':opponentHere()?'● LIVE · BOTH IN THE PARK':'INDIVIDUAL ROLLS SYNC LIVE';e.classList.toggle('here',opponentHere());}}
function waitingRoom(m){main.innerHTML=`<div class="setup"><button class="back" id="waitingBack">← Clubhouse</button><div class="eyebrow">YOUR GAME IS IN FIND A GAME</div><h2>One open seat. Big possibilities.</h2><section class="panel"><h3>${teamLabel(m.teams[0])} · ${m.state.innings} innings</h3><span class="pill">${m.locked?'🔒 JOIN CODE REQUIRED':'ANY PLAYER CAN JOIN'}</span><p class="note" style="margin-top:18px">Your opponent can find this ballgame inside the app. This screen opens the field when someone joins.</p><label>Game ID</label><div class="code">${esc(m.code)}</div><button class="btn outline" id="copyCode">Copy game ID</button></section></div>`;$('#waitingBack').onclick=lobby;$('#copyCode').onclick=()=>copy(m.code);}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied.');}catch{showModal('Copy this.',`<textarea readonly style="width:100%;min-height:130px">${esc(text)}</textarea>`);}}
function isMine(){return session?.kind==='offline'||current?.status==='active'&&current.turnUid===Cloud.user?.uid;}
function canClutch(){if(!session||!isMine()||!session.rolls?.length||busy||replaying)return false;const team=session.start.half;return !session.state.clutch?.[team]&&!session.rolls.some(r=>r.clutch);}
function completed(){return !!session?.finalized;}
function formatInning(s){return s.over?'FINAL':`${s.half===0?'▲ TOP':'▼ BOT'} ${s.inning}`;}
function lineTable(s,ts){const count=Math.max(s.innings,s.inning);return `<div class="line-table-wrap"><table class="line-table"><thead><tr><th>TEAM</th>${Array.from({length:count},(_,i)=>`<th>${i+1}</th>`).join('')}<th>R</th><th>H</th></tr></thead><tbody>${ts.map((t,j)=>`<tr><td>${teamLabel(t)}</td>${Array.from({length:count},(_,i)=>`<td>${s.lines[j][i]??(s.over&&j===1&&i===s.inning-1?'×':'–')}</td>`).join('')}<td class="total">${s.runs[j]}</td><td>${s.hits[j]}</td></tr>`).join('')}</tbody></table></div>`;}
function renderGame(display=null){
 if(!session)return;const online=session.kind==='online',s=display||(online?displayedState:null)||session.state,ts=session.teams,mine=isMine(),spectator=online&&!current.players.includes(Cloud.user.uid),behind=online&&displayRevision<current.revision,own=online?current.players.indexOf(Cloud.user.uid):0,cpu=!online&&session.mode==='solo'&&session.start.half===1&&!completed(),final=completed(),lastTurn=online?current.lastTurn:session.history?.at(-1),unseen=online&&lastTurn&&lastTurn.by!==Cloud.user.uid&&read(`seen.${session.code}`,0)<current.seq&&!behind&&!eventRunning,request=online?read('request.'+session.code,null):null,activeTeam=session.pending?session.start.half:s.half,bid=s.over?null:batter(s),used=s.clutch||[false,false],batstats=s.stats[activeTeam].reduce((a,p)=>{for(const k of ['h','ab','hr','bb','rbi'])a[k]+=(p[k]||0);return a;},{h:0,ab:0,hr:0,bb:0,rbi:0});
 main.innerHTML=`<div class="game-header row"><div><button class="back" id="gameBack" style="margin-bottom:10px">← ${returnLeague?'League':online?'Clubhouse':'Home'}</button><h2>${final?'That’s a ballgame.':eventRunning?'The ballpark is live.':'Let’s play some ball.'}</h2><span class="eyebrow">${spectator?'LEAGUE SPECTATOR':online?'ONLINE BALLGAME':session.mode==='solo'?'SOLO':'PASS & PLAY'} / ${s.innings} INNINGS${s.inning>s.innings?' / EXTRAS':''}</span></div><div class="game-tools">${online?'<span class="live-status" id="onlinePresence"></span>':''}<button class="speed" id="speed">${speed}× speed</button></div></div>
 ${final?`<section class="final-banner"><div class="eyebrow">FINAL · ${session.state.runs.join(' – ')}</div><h2>${reportCache?esc(reportCache.headline):teamLabel(ts[session.state.winner])+' win!'}</h2>${reportCache?`<p class="note">${esc(reportCache.paragraphs[0])}</p>`:''}<div class="buttonrow" style="justify-content:center"><button class="btn" id="fullRecap">Game recap</button><button class="btn secondary" id="boxScore">Box score & stats</button><button class="btn outline" id="rematch">${online?'New game':'Play again'}</button></div></section>`:''}
 ${replaying?'<div class="replaybar"><strong id="replayStatus">Turn replay</strong><button class="btn secondary" id="stopReplay">Skip →</button></div>':behind||eventRunning?'<div class="replaybar livebar"><strong id="liveNow"><span class="live-dot"></span>Watching individual rolls live</strong><button class="btn secondary" id="catchUp">Catch up →</button></div>':unseen?'<div class="replaybar"><strong>Your opponent finished a turn.</strong><div class="tabs"><button id="watchTurn" class="active">Watch turn</button><button id="skipTurn">Skip →</button></div></div>':''}
 ${session.pending&&!final&&mine&&!replaying?`<div class="waiting"><strong>${session.state.over?'Provisional final.':'The side is retired.'}</strong> ${canClutch()?'Use Clutch Batter to reroll that last play, or keep it.':'Confirm the result to hand over the field.'}<button class="btn wide" id="endTurn" style="margin-top:10px" ${busy?'disabled':''}>${session.state.over?'Keep play & finish game':'Keep play & end inning →'}</button></div>`:''}
 ${request&&!busy?'<div class="waiting">A roll is waiting to sync. Retry the exact saved dice.<div class="buttonrow"><button class="btn" id="retryRequest">Retry saved roll</button><button class="btn outline" id="discardRequest">Discard unsent request</button></div></div>':''}
 ${uiError?`<p class="error" role="alert">${esc(uiError)}</p>`:''}
 <div class="game-layout"><div class="game-stage"><section class="stadium"><div class="scoreboard"><div class="team-score"><div><div class="teamname">${teamLabel(ts[0])}</div><small>AWAY${!s.over&&s.half===0?' · AT BAT':''}</small></div><span class="score">${s.runs[0]}</span></div><div class="inning">${formatInning(s)}<div class="outdots">${[0,1,2].map(i=>`<i class="${i<s.outs?'on':''}"></i>`).join('')}</div></div><div class="team-score home"><div><div class="teamname">${teamLabel(ts[1])}</div><small>HOME${!s.over&&s.half===1?' · AT BAT':''}</small></div><span class="score">${s.runs[1]}</span></div></div><div class="field" id="field" aria-label="Cardpark stadium and baseball field"></div><div class="field-bottom"><span>${s.over?'FINAL':`AT BAT <strong>${esc(ts[s.half].players[bid].name)}</strong>`}</span><span>${s.outs} OUT${s.outs!==1?'S':''} · ${s.bases.filter(x=>x!==null).length} ON BASE</span></div></section>
 <div class="control-panel"><div class="dice-pair" id="dice">${(session.lastDice||[1,1]).map(dieHTML).join('')}</div><div><button class="roll-btn" id="roll" ${busy||replaying||behind||final||session.pending||!mine||cpu||request||unseen?'disabled':''}>${busy?'In play…':final?'Final':session.pending?'Choose your finish':!mine?'Their turn':cpu?'Park crew batting…':'Roll the dice ↗'}</button><div class="control-caption">${online?'Every roll saves and streams immediately':'Two dice. One at-bat.'}</div></div></div>
 <div class="clutch-panel"><div><strong>✦ Clutch Batter</strong><small>${used[session.start.half]?'USED THIS GAME':'ONE REROLL PER TEAM / GAME'}</small></div><button class="btn clutch-btn" id="clutch" ${!canClutch()||behind||cpu||final||request?'disabled':''}>Reroll last play</button></div>
 <section class="panel" style="margin-top:16px"><div class="row"><h3 style="margin:0">${teamLabel(ts[activeTeam])}</h3><span class="eyebrow">THE STARTING FOUR</span></div><div class="roster-list">${ts[activeTeam].players.map((p,i)=>`<div class="roster-card ${!s.over&&i===bid&&activeTeam===s.half?'active':''}">${cardHTML(p,ts[activeTeam])}<small>${s.stats[activeTeam][i].h} H · ${s.stats[activeTeam][i].r} R · ${s.stats[activeTeam][i].rbi} RBI</small></div>`).join('')}</div></section></div>
 <aside class="sidebar"><section class="panel"><h3>The linescore</h3>${lineTable(s,ts)}<div class="buttonrow"><button class="btn outline" id="gameStats">Box score</button><button class="btn secondary" id="history">Replay history</button></div></section><section class="panel"><h3>At the plate</h3><div class="stat-strip"><div><b>${battingLine({...batstats,tb:s.stats[activeTeam].reduce((n,p)=>n+(p.tb||0),0)}).avg}</b><small>AVG</small></div><div><b>${batstats.hr}</b><small>HR</small></div><div><b>${batstats.bb}</b><small>BB</small></div></div><p class="fineprint">${teamLabel(ts[activeTeam])} · ${used[0]?'Away clutch used':'Away clutch ready'} · ${used[1]?'Home clutch used':'Home clutch ready'}</p><button class="btn outline wide" id="scout">Scout the odds</button></section><section class="panel logpanel"><h3>From the dugout</h3><div class="playlog">${logHTML(session.log||[],ts)}</div></section></aside></div>`;
 paintField($('#field'),s,ts);updatePresenceLabel();$('#gameBack').onclick=()=>{if(busy&&!eventRunning&&!replaying){toast('Finishing this roll…');return;}if(returnLeague)openLeague(returnLeague);else online?lobby():home();};$('#speed').onclick=()=>{speed=speed===1?2:speed===2?4:1;write('speed',speed);setSpeed(speed);$('#speed').textContent=speed+'× speed';};$('#roll').onclick=()=>takeRoll(false);$('#clutch').onclick=clutchDialog;$('#endTurn')?.addEventListener('click',finishHalf);$('#catchUp')?.addEventListener('click',catchUp);$('#gameStats').onclick=boxScore;$('#history').onclick=showHistory;$('#scout').onclick=scoutDialog;$('#fullRecap')?.addEventListener('click',showRecap);$('#boxScore')?.addEventListener('click',boxScore);$('#rematch')?.addEventListener('click',()=>setup(online?'online':session.mode));$('#retryRequest')?.addEventListener('click',()=>takeRoll(request.type==='clutch',true));$('#discardRequest')?.addEventListener('click',()=>{localActions.delete(request.id);remove('request.'+session.code);renderGame();pumpActions();});$('#watchTurn')?.addEventListener('click',()=>playReplay(lastTurn));$('#skipTurn')?.addEventListener('click',()=>{write(`seen.${session.code}`,current.seq);renderGame();});$('#stopReplay')?.addEventListener('click',()=>{replayEpoch++;replaying=false;busy=false;renderGame();pumpActions();});if(final&&!reportCache&&!reportLoading)prepareReport();scheduleAI();
}
function logHTML(log,ts,limited=true){return log.length?(limited?log.slice(-30):[...log]).reverse().map(p=>`<div class="log-item"><strong>${esc(ts[p.team].players[p.batter].name)}</strong> · ${esc(p.label)}${p.runs?' · +'+p.runs+' R':''}${p.clutch?' ✦ CLUTCH':''}<span>${p.half===0?'Top':'Bottom'} ${p.inning} · [${p.dice.join(' · ')}]</span></div>`).join(''):'<div class="empty">Fresh grass. Clean slate.</div>';}
function clutchDialog(){if(!canClutch())return;const old=session.rolls.at(-1);showModal('Time for a clutch at-bat?',`<p class="note">Undo the last play and reroll both dice. You must keep the new result, even if it is worse. This is your team’s only Clutch Batter this game.</p><p class="note">Current roll: <strong>${old.dice.join(' · ')}</strong></p><button class="btn wide clutch-btn" id="useClutch">Use Clutch Batter ✦</button>`);$('#useClutch').onclick=()=>{closeModal();takeRoll(true);};}
function scoutDialog(){let s=session.state;if(session.pending&&session.rolls.length)s=replay(session.start,session.rolls.slice(0,-1));if(s.over)return;const odds=situationOdds(s);showModal('A little scouting goes a long way.',`<div class="stat-strip"><div><b>${Math.round(odds.onbase*100)}%</b><small>REACH BASE</small></div><div><b>${Math.round(odds.out*100)}%</b><small>OUT RESULT</small></div><div><b>${odds.runs.toFixed(2)}</b><small>EXPECTED RUNS</small></div></div><p class="note">${session.pending?'These odds describe rerolling your final at-bat.':'These are the odds for the next at-bat with the current runners.'} A sacrifice fly is an out result but can still score a run.</p><p class="note">Clutch Batter is most valuable when you have runners aboard, are down to your final out, or need one run late. Spending it early might save an inning; holding it might save the game. The reroll always uses the same fair dice.</p>`);}
async function takeRoll(clutch=false,retry=false){
 if(!session||busy||replaying||completed()||!isMine()||session.pending&&!clutch&&!retry)return;if(clutch&&!retry&&!canClutch())return;if(session.kind==='online'&&displayRevision<current.revision)return;
 const g=generation;busy=true;uiError='';clearTimeout(autoTimer);let action;
 try{
  if(session.kind==='online'){
   let req=read('request.'+session.code,null);if(!req){req={id:crypto.randomUUID(),revision:current.revision,dice:rollDice(),type:clutch?'clutch':'roll'};if(!write('request.'+session.code,req))return;}localActions.add(req.id);const b=$('#roll');if(b){b.disabled=true;b.textContent='Saving roll…';}
   action=await Cloud.play(session.code,req.revision,req.dice,req.type==='clutch',req.id);if(g!==generation)return;
   if(current.revision<action.revision)setMatch(await Cloud.getMatch(session.code));remove('request.'+session.code);
   if(action.revision>displayRevision){const {before,result}=actionResult(action);displayedState=before;renderGame(before);await animateDice($('#dice'),action.dice);if(g!==generation)return;await animatePlay($('#field'),before,result,session.teams);if(g!==generation)return;displayedState=clone(result.state);displayRevision=action.revision;seenActions.add(action.id);session.lastDice=action.dice;actionQueue=actionQueue.filter(a=>a.revision>displayRevision);}
   localActions.delete(req.id);
  }else{
   const x=playFromTurn(session.start,session.rolls,rollDice(),clutch);session.rolls=x.rolls;session.state=x.result.state;session.pending=x.result.event.endTurn;session.log=[...gameEvents(session.history||[]),...turnLog(session.start,session.rolls)];session.lastDice=x.result.event.dice;saveSession();renderGame(x.before);await animateDice($('#dice'),x.result.event.dice);if(g!==generation)return;await animatePlay($('#field'),x.before,x.result,session.teams);
  }
 }catch(e){uiError=errorText(e);}finally{if(g===generation){busy=false;renderGame();pumpActions();}}
}
async function finishHalf(){
 if(!session?.pending||busy)return;const g=generation;busy=true;uiError='';
 try{if(session.kind==='online'){await Cloud.finishTurn(session.code,current.seq,current.revision);if(g!==generation)return;setMatch(await Cloud.getMatch(session.code));}
 else {session.history.push({index:session.history.length,start:clone(session.start),rolls:clone(session.rolls),time:Date.now()});session.pending=false;session.finalized=session.state.over;session.start=clone(session.state);session.rolls=[];saveSession();if(session.finalized)archiveOffline();}
 }catch(e){uiError=errorText(e);}finally{if(g===generation){busy=false;renderGame();pumpActions();}}
}
function archiveOffline(){const archive=read('archives',[]);if(!archive.some(m=>m.id===session.id)){const compact=clone(session);compact.teams.forEach(t=>t.players.forEach(p=>p.photo=''));archive.push(compact);write('archives',archive.slice(-35));}}
function scheduleAI(){clearTimeout(autoTimer);if(document.hidden||busy||replaying||!session||session.kind!=='offline'||session.mode!=='solo'||session.start.half!==1||completed())return;autoTimer=setTimeout(async()=>{const last=session.rolls.at(-1),bad=last?applyRecord(replay(session.start,session.rolls.slice(0,-1)),last).event.retired.length>0:false;if(bad&&canClutch()&&(session.pending||session.state.runs[1]<session.state.runs[0])&&Math.random()<.65){await takeRoll(true);}else if(session.pending)await finishHalf();else await takeRoll(false);},800/speed);}
async function showHistory(){if(busy)return;showModal('Every inning has a story.','<p class="note" id="historyStatus">Loading…</p><div class="history-list" id="historyItems"></div>');try{const turns=session.kind==='online'?await Cloud.history(session.code):session.history;if(!$('#historyItems'))return;$('#historyStatus').textContent=turns.length?'Choose a completed half-inning.':'No completed half-innings yet.';$('#historyItems').innerHTML=[...turns].reverse().map((t,i)=>`<button data-history="${turns.length-1-i}">${t.start.half===0?'▲ Top':'▼ Bottom'} ${t.start.inning} · ${t.rolls.length} at-bats${t.rolls.some(r=>r.clutch)?' · ✦ CLUTCH':''} <span style="float:right">Watch →</span></button>`).join('');modal.querySelectorAll('[data-history]').forEach(b=>b.onclick=()=>{closeModal();playReplay(turns[+b.dataset.history]);});}catch(e){if($('#historyStatus'))$('#historyStatus').textContent=errorText(e);}}
async function playReplay(turn){if(!turn||busy)return;const g=generation,id=++replayEpoch;busy=true;replaying=true;if(session.kind==='online')write(`seen.${session.code}`,current.seq);let state=clone(turn.start);try{for(let i=0;i<turn.rolls.length;i++){if(g!==generation||id!==replayEpoch)break;const result=applyRecord(state,turn.rolls[i]);renderGame(state);$('#replayStatus').textContent=`Replay · at-bat ${i+1}/${turn.rolls.length}${turn.rolls[i].clutch?' · CLUTCH REROLL':''}`;await animateDice($('#dice'),turn.rolls[i].dice);if(g!==generation||id!==replayEpoch)break;await animatePlay($('#field'),state,result,session.teams);state=result.state;}}finally{if(g===generation&&id===replayEpoch){busy=false;replaying=false;renderGame();pumpActions();}}}
function battingTable(roster,stats){return `<div class="line-table-wrap"><table class="recapstats"><thead><tr><th>PLAYER</th><th>AB</th><th>H</th><th>R</th><th>RBI</th><th>HR</th><th>BB</th><th>K</th><th>AVG</th><th>OPS</th></tr></thead><tbody>${stats.map((p,i)=>`<tr><td>${esc(roster[i].name)}</td>${['ab','h','r','rbi','hr','bb','k'].map(k=>`<td>${p[k]||0}</td>`).join('')}<td>${battingLine(p).avg}</td><td>${battingLine(p).ops}</td></tr>`).join('')}</tbody></table></div>`;}
function boxScore(){const s=session.state;showModal('Every card counts.',`${lineTable(s,session.teams)}${session.teams.map((t,i)=>`<h3 style="margin-top:24px">${teamLabel(t)}</h3>${battingTable(t.players,s.stats[i])}`).join('')}<p class="fineprint" style="margin-top:18px">AVG = batting average. OPS = on-base percentage + slugging. Clutch replacements reverse the original play’s stats.</p>`);}
async function prepareReport(){if(reportLoading||!completed())return;const g=generation,id=session.id,s=clone(session.state),ts=clone(session.teams);reportLoading=true;try{const turns=session.kind==='online'?await Cloud.history(session.code):session.history;const r=recap(s,ts,turns);if(g===generation&&session?.id===id){reportCache=r;reportLoading=false;if(!busy&&!replaying)renderGame();}return r;}catch(e){reportLoading=false;uiError=errorText(e);}}
async function showRecap(){if(!completed())return;const recapGeneration=generation,recapId=session.id;showModal('The game story.','<p class="note">Writing the final word…</p>');if(!reportCache){reportLoading=false;await prepareReport();}if(recapGeneration!==generation||session?.id!==recapId)return;if(!reportCache){$('#modalBody').innerHTML+=`<p class="error">${esc(uiError||'Could not load the recap. Try again.')}</p>`;return;}const r=reportCache,ts=session.teams;showModal('The game story.',`<div class="recap-hero"><span class="eyebrow">CARDPARK POSTGAME</span><h2>${esc(r.headline)}</h2><div class="recap-score">${session.state.runs[0]} <span>–</span> ${session.state.runs[1]}</div><p>${teamLabel(ts[0])} vs. ${teamLabel(ts[1])}</p></div><div class="recap-copy">${r.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}</div>${r.star?`<div class="star-card"><div class="star-photo">${cardHTML(ts[r.star.t].players[r.star.i],ts[r.star.t])}</div><div><div class="eyebrow">PLAYER OF THE GAME</div><h3>${esc(ts[r.star.t].players[r.star.i].name)}</h3><strong>${r.star.h} H · ${r.star.rbi} RBI · ${r.star.r} R${r.star.hr?' · '+r.star.hr+' HR':''}</strong></div></div>`:''}<h3 style="margin-top:24px">The moments that mattered</h3><div class="moment-list">${r.moments.map(p=>`<div class="moment"><span>${p.half===0?'TOP':'BOT'} ${p.inning}</span><div><strong>${esc(ts[p.team].players[p.batter].name)} · ${esc(p.label)}${p.clutch?' ✦ CLUTCH':''}</strong><small>${p.runs?`${p.runs} run${p.runs===1?'':'s'} scored · `:''}${p.afterRuns.join(' – ')}${p.originalDice?` · replaced [${p.originalDice.join(', ')}]`:''}</small></div></div>`).join('')||'<p class="note">The linescore tells the story.</p>'}</div><div class="buttonrow"><button class="btn" id="recapBox">Full box score</button><button class="btn outline" id="copyRecap">Copy recap</button><button class="btn secondary" id="recapPlays">Play-by-play</button></div>`);$('#recapBox').onclick=boxScore;$('#copyRecap').onclick=()=>copy(r.headline+'\n\n'+r.paragraphs.join('\n\n'));$('#recapPlays').onclick=()=>showModal('From first pitch to final out.',`<div class="playlog" style="max-height:none">${logHTML(r.events,ts,false)}</div>`);}
function statsHTML(data,title){const {total:t,cards}=data;return `<section class="panel"><div class="eyebrow">${esc(title)}</div><h2>${t.w}–${t.l} <span class="muted">record</span></h2><div class="stat-strip"><div><b>${t.gp}</b><small>GAMES</small></div><div><b>${t.rf}</b><small>RUNS FOR</small></div><div><b>${t.ra}</b><small>RUNS AGAINST</small></div><div><b>${battingLine(t).avg}</b><small>TEAM AVG</small></div></div><p class="note">${t.h} H · ${t.hr} HR · ${t.bb} BB · ${t.k} K · ${t.rbi} RBI</p></section><section class="panel" style="margin-top:15px"><h3>Card career stats</h3>${cards.length?battingTable(cards,cards):'<div class="empty">Finish a game to start building your stats.</div>'}<p class="fineprint">Cards are grouped by player name and jersey number. Only confirmed final games count. Offline stats track the away team you control.</p></section>`;}
async function showStats(online=false){if(online&&!Cloud.user){authDialog();return;}const records=online?onlineList:read('archives',[]);showModal(online?'Online career.':'Your offline career.',statsHTML(career(records,online?Cloud.user.uid:null),online?'ONLINE GAMES':'SAVED ON THIS DEVICE'));}
function createLeagueDialog(){showModal('Build your own league.',`<p class="note">Your current lineup, <strong>${teamLabel(teams[0])}</strong>, is your league team. Other players join from the Leagues tab.</p><form id="leagueForm"><div class="form-group"><label for="leagueName">League name</label><input id="leagueName" maxlength="32" required placeholder="The Backyard League"></div><div class="form-grid"><div><label for="leagueCap">Maximum teams</label><select id="leagueCap">${Array.from({length:10},(_,i)=>`<option ${i+3===8?'selected':''}>${i+3}</option>`).join('')}</select></div><div><label for="leagueGames">Games per team</label><input id="leagueGames" type="number" min="1" max="30" value="6" required></div><div><label for="leagueInnings">Innings per game</label><select id="leagueInnings"><option>3</option><option selected>6</option><option>9</option></select></div><div><label for="leaguePlayoffs">Playoff places</label><select id="leaguePlayoffs"><option>2</option><option selected>4</option><option>8</option></select></div></div><p class="note">Start once 3–12 teams have joined. Playoff places are capped to the largest supported bracket that fits your teams. Odd team counts need an even number of games per team.</p><p class="error" id="leagueError"></p><button class="btn wide" id="createLeagueSubmit">Create league</button></form>`);$('#leagueForm').onsubmit=async e=>{e.preventDefault();$('#createLeagueSubmit').disabled=true;try{const id=await Cloud.createLeague(teams[0],{name:$('#leagueName').value,cap:$('#leagueCap').value,gamesPerTeam:$('#leagueGames').value,innings:$('#leagueInnings').value,playoffTeams:$('#leaguePlayoffs').value});closeModal();openLeague(id);}catch(err){$('#leagueError').textContent=errorText(err);$('#createLeagueSubmit').disabled=false;}};}
async function openLeague(id){const g=enter('league');current=null;session=null;leagueCurrent=null;main.innerHTML='<div class="empty">Opening the league office…</div>';try{keep(g,await Cloud.watchLeague(id,l=>{if(g!==generation)return;leagueCurrent=l;renderLeague();},e=>{if(g===generation){main.innerHTML=`<p class="error">${esc(errorText(e))}</p><button class="btn" id="leagueFail">Clubhouse</button>`;$('#leagueFail').onclick=lobby;}}));}catch(e){toast(errorText(e));lobby();}}
function renderLeague(){
 const l=leagueCurrent;if(!l)return;const uid=Cloud.user.uid,member=l.memberIds.includes(uid),owner=l.owner===uid,rows=standings(l),season=JSON.parse(l.seasonJSON),bracket=JSON.parse(l.playoffsJSON),team=id=>l.entries.find(t=>t.uid===id)?.name||'TBD',mine=season.filter(g=>g.away===uid||g.home===uid),champ=l.champion?team(l.champion):'';
 const fixture=g=>`<div class="fixture"><div><span class="eyebrow">${g.stage==='season'?'REGULAR SEASON · '+g.id:'PLAYOFF · '+g.id}</span><strong>${esc(team(g.away))} <span class="muted">at</span> ${esc(team(g.home))}</strong><small>${g.result?g.result.runs.join(' – ')+' · '+esc(team(g.result.winner))+' win':'Scheduled · '+l.innings+' innings'}</small></div>${member&&(g.result||[g.away,g.home].includes(uid))?`<button class="btn ${g.result?'outline':''}" data-fixture="${g.id}">${g.result?'Recap':'Play →'}</button>`:'<span class="pill">WAITING</span>'}</div>`;
 main.innerHTML=`<div class="setup league-page"><button class="back" id="leagueBack">← Clubhouse</button><div class="row"><div><div class="eyebrow">CARDPARK LEAGUES</div><h2>${esc(l.name)}</h2></div><span class="pill">${esc(l.status.toUpperCase())}</span></div><p class="note">${l.memberIds.length}/${l.cap} teams · ${l.gamesPerTeam} games per team · ${l.innings} innings</p>${champ?`<div class="final-banner"><div class="eyebrow">LEAGUE CHAMPIONS</div><h2>🏆 ${esc(champ)}</h2><p class="note">The season belongs to them.</p></div>`:''}${!member&&l.status==='forming'&&l.memberIds.length<l.cap?'<button class="btn wide" id="joinLeague">Join this league with my lineup</button>':''}<p class="error" id="leagueActionError"></p>${l.status==='forming'?`<section class="panel"><h3>The founding clubs</h3>${l.entries.map(t=>`<div class="member-row"><span class="team-dot" style="background:${/^#[a-f0-9]{6}$/i.test(t.color)?t.color:'#315c48'}"></span><strong>${esc(t.name)}</strong>${t.uid===l.owner?'<span class="pill">COMMISSIONER</span>':''}</div>`).join('')}${owner?`<div class="form-grid" style="margin-top:20px"><div><label for="startGames">Games per team</label><input id="startGames" type="number" min="1" max="30" value="${l.gamesPerTeam}"></div><div><label for="startPlayoffs">Playoff teams</label><select id="startPlayoffs">${[2,4,8].map(n=>`<option ${l.playoffTeams===n?'selected':''}>${n}</option>`).join('')}</select></div></div><p class="note">${l.memberIds.length<3?'Waiting for at least three teams.':'Ready when you are.'} Starting locks all rosters and generates an equal schedule.</p><button class="btn wide" id="startLeague" ${l.memberIds.length<3?'disabled':''}>Start season & generate schedule</button>`:'<p class="note">The commissioner starts the season after everyone joins.</p>'}</section>`:`<section class="panel"><h3>Regular-season standings</h3><div class="line-table-wrap"><table class="recapstats"><tr><th># / TEAM</th><th>W</th><th>L</th><th>PCT</th><th>RF</th><th>RA</th><th>DIFF</th></tr>${rows.map(r=>`<tr><td>${r.seed}. ${esc(r.name)}</td><td>${r.w}</td><td>${r.l}</td><td>${r.pct.toFixed(3)}</td><td>${r.rf}</td><td>${r.ra}</td><td>${r.diff>0?'+':''}${r.diff}</td></tr>`).join('')}</table></div><p class="fineprint">Win percentage → wins → head-to-head → run differential → runs scored. Final ties use club name, then account ID, for a stable seed.</p></section>${bracket.length?`<section class="panel" style="margin-top:18px"><h3>🏆 The playoff bracket</h3><div class="bracket">${bracket.map((round,i)=>`<div class="bracket-round"><div class="eyebrow">${round.length===1?'CHAMPIONSHIP':round.length===2?'SEMIFINALS':'QUARTERFINALS'}</div>${round.map(fixture).join('')}</div>`).join('')}</div></section>`:'<div class="waiting">Playoffs seed automatically once every regular-season fixture has a confirmed final score.</div>'}<section class="panel" style="margin-top:18px"><h3>${member?'Your regular-season schedule':'Regular-season schedule'}</h3>${(member?mine:season).map(fixture).join('')||'<p class="note">No fixtures.</p>'}</section>${member?`<details class="panel" style="margin-top:16px"><summary>All ${season.length} regular-season games</summary>${season.map(fixture).join('')}</details>`:''}`}</div>`;
 $('#leagueBack').onclick=lobby;$('#joinLeague')?.addEventListener('click',async()=>{const b=$('#joinLeague');b.disabled=true;try{await Cloud.joinLeague(l.id,teams[0]);}catch(e){$('#leagueActionError').textContent=errorText(e);b.disabled=false;}});$('#startLeague')?.addEventListener('click',async()=>{const b=$('#startLeague');b.disabled=true;try{await Cloud.startLeague(l.id,$('#startGames').value,$('#startPlayoffs').value);}catch(e){$('#leagueActionError').textContent=errorText(e);b.disabled=false;}});main.querySelectorAll('[data-fixture]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const code=await Cloud.ensureLeagueGame(l.id,b.dataset.fixture);openMatch(code,l.id);}catch(e){$('#leagueActionError').textContent=errorText(e);b.disabled=false;}});
}
window.addEventListener('online',()=>{toast('Connection restored.');sendPresence();});window.addEventListener('offline',()=>{updatePresenceLabel();toast('Offline games still work. Online rolls wait for a connection.');});
document.addEventListener('visibilitychange',()=>{parkAudio(view==='game');if(document.hidden){saveSession();clearTimeout(autoTimer);}else{scheduleAI();pumpActions();}if(view==='game')sendPresence(!document.hidden);});
window.addEventListener('beforeunload',()=>{saveSession();if(view==='game')sendPresence(false);});
home();
if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').then(r=>r.addEventListener('updatefound',()=>{const w=r.installing;w?.addEventListener('statechange',()=>{if(w.state==='installed'&&navigator.serviceWorker.controller)toast('Update ready. Close all Cardpark windows and reopen.');});})).catch(()=>{});
if(location.hash.startsWith('#join=')){write('invite',location.hash.slice(6).toUpperCase());history.replaceState(null,'',location.pathname+location.search);lobby().then(()=>{if(Cloud.user)joinDialog(read('invite',''));});}
